    for target, replacement in replacements:
        if target not in modified:
            print(f"ERROR: target text not found in source file:\n{target[:100]}...")
            return False
        # Make sure there is only one occurrence to avoid wrong replacement
        if modified.count(target) > 1:
            print(f"WARNING: multiple occurrences of target text found:\n{target[:100]}...")
        modified = modified.replace(target, replacement)
        
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(modified)
        
    # Verification: strip XML speaker tags and check character-for-character equivalence
    stripped = re.sub(r'</?(?:odysseus|telemachus|others)>', '', modified)
    if stripped == content:
        print("SUCCESS: Tagged file created and verified. Stripping matches original character-for-character!")
        return True
    else:
        print("ERROR: Verification failed! Stripping tags does not preserve original content exactly.")
        # Find difference
        for i, (c1, c2) in enumerate(zip(content, stripped)):
            if c1 != c2:
                print(f"Diff at index {i}: original {repr(content[i:i+20])} vs stripped {repr(stripped[i:i+20])}")
                break
        return False

